INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Log-Dateien nur für Fehler relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Infos und Audits"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Log-Analyse?', 3, '[{"text": "Fehlerquellen identifizieren", "correct": true, "because": "Hilft bei Debugging"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Fokus"}, {"text": "UI anpassen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Log-Analyse?', 5, '[{"text": "Log-Dateien", "correct": true, "because": "Primäre Datenquelle"}, {"text": "Fehlerquellen", "correct": true, "because": "Ziel der Analyse"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Logs enthalten Zeitstempel. b) Analyse ist immer manuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann automatisiert sein"}, {"text": "Beides stimmt", "correct": false, "because": "Automatisierung möglich"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Log-Analyse?', 4, '[{"text": "Zeitstempel", "correct": false, "because": "Hilft bei Chronologie"}, {"text": "Fehlermeldungen", "correct": false, "because": "Kern der Analyse"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Logs nur Fehler protokollieren?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Warnungen und Infos"}, {"text": "Ja", "correct": false, "because": "Mehr als Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für die Log-Analyse?', 3, '[{"text": "Log-Parser", "correct": true, "because": "Verarbeitet Logs effizient"}, {"text": "Texteditor", "correct": false, "because": "Nur Anzeige"}, {"text": "Compiler", "correct": false, "because": "Für Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Log-Analyse?', 5, '[{"text": "Fehlerlokalisierung", "correct": true, "because": "Zeigt Ursachen"}, {"text": "Systemüberwachung", "correct": true, "because": "Verfolgt Zustand"}, {"text": "Datenkompression", "correct": false, "because": "Kein Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Logs sind für Debugging essenziell. b) Analyse ist immer zeitaufwendig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann automatisiert sein"}, {"text": "Beides stimmt", "correct": false, "because": "Effizienz möglich"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Log-Analyse?', 4, '[{"text": "Log-Dateien", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Suchmuster", "correct": false, "because": "Hilft bei Filterung"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Enthalten Logs immer Fehlerdetails?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Log-Level"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen suche ich in Logs?', 4, '[{"text": "Fehlercodes", "correct": true, "because": "Zeigen Probleme"}, {"text": "Zeitstempel", "correct": true, "because": "Zeigen Wann"}, {"text": "UI-Layout", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Log-Analyse nur für große Systeme ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Log-Analyse?', 3, '[{"text": "Relevante Einträge finden", "correct": true, "because": "Zielt auf Fehler"}, {"text": "Schnelle Durchsicht", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Designanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Logs helfen bei Problemlösung. b) Analyse ist nur für Entwickler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Auch Ops nutzt sie"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Log-Analyse?', 5, '[{"text": "Unentdeckte Fehler", "correct": true, "because": "Keine Rückmeldung"}, {"text": "Schweres Debugging", "correct": true, "because": "Fehlende Infos"}, {"text": "Schnellere Systeme", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse unwichtig?', 3, '[{"text": "Log-Level", "correct": false, "because": "Zeigt Schwere"}, {"text": "Fehlerbeschreibung", "correct": false, "because": "Gibt Details"}, {"text": "Serverdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich Logs ohne Tools analysieren?', 3, '[{"text": "Ja", "correct": true, "because": "Manuell möglich"}, {"text": "Nein", "correct": false, "because": "Tools nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Logs immer strukturiert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Können unstrukturiert sein"}, {"text": "Ja", "correct": false, "because": "Format variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Fehler in Logs zu finden?', 4, '[{"text": "Filterung", "correct": true, "because": "Isoliert relevante Einträge"}, {"text": "UI-Refresh", "correct": false, "because": "Kein Bezug"}, {"text": "Code-Neustart", "correct": false, "because": "Keine Analyse"}]');
